<?php
namespace App\Services\Creative;
use App\Models\{CreativeRequest,CreativeComment,PerformanceEvent,User};
use Illuminate\Support\Facades\DB;
class CreativeProjection {
 public function item(CreativeRequest $r,User $actor):array {
  $submissionDeadline=$r->firstSubmission?->metadata['requested_deadline']??$r->requested_deadline?->toIso8601String();
  $owner=$r->assignee; $requester=$r->requester;$reviewer=$r->reviewer;
  $waiting=in_array($r->stage,['in_review','delivered']);$next=match($r->stage){'in_review'=>$reviewer?->name??'Reviewer not recorded','delivered'=>'Creative HOD: final verification','brief_received','backlog'=>'Creative HOD: planning','needs_info'=>$requester?->name??'Requester','completed','archived'=>'No action outstanding',default=>$owner?->name??'Unassigned'};
  $next=$r->is_group?($r->stage==='completed'?'All work packages verified':'Work package owners and reviewers'):$next;
  $raster=$r->attachments->first(fn($a)=>in_array($a->mime,['image/jpeg','image/png','image/webp','video/mp4','video/webm']));
  return ['is_group'=>$r->is_group,'parent_request_id'=>$r->parent_request_id,'id'=>$r->id,'reference'=>$r->reference,'title'=>$r->title,'brief'=>$r->brief,'client'=>$r->client,'creative_type'=>$r->creative_type,'department'=>$r->department,'priority'=>$r->priority,'stage'=>$r->stage,'visibility'=>$r->visibility,'legacy'=>$r->legacy,'legacy_received_date_only'=>$r->legacy&&$r->received_at!==null,'revision'=>$r->revision,'iteration'=>$r->iteration,'requester'=>['id'=>$r->requester_id,'name'=>$requester?->name??($r->requester_snapshot['name']??'Not recorded'),'department'=>$r->requester_snapshot['department']??$r->department,'role'=>$r->requester_snapshot['role']??'Not recorded'],'assignee'=>['id'=>$r->assignee_id,'name'=>$owner?->name??($r->assignee_snapshot['name']??'Unassigned'),'photo'=>$owner?->profilePhotoUrl()],'reviewer'=>['id'=>$r->reviewer_id,'name'=>$reviewer?->name??'Not recorded'],'next_action'=>$next,'performance_weight'=>$r->task?->weight_approved_at?$r->task->performance_weight:null,'estimated_hours'=>$r->estimated_hours,'quality_score'=>$r->quality_score,'blocker'=>$r->blocker,'blocker_owner'=>$r->blocker_owner,'overdue'=>!in_array($r->stage,['backlog','completed','archived'])&&$r->requested_deadline?->isPast()&&!$waiting&&!$r->first_submitted_at,'review_overdue'=>$r->stage==='in_review'&&$r->review_due_at?->isPast(),'on_time_submission'=>$r->first_submitted_at&&$submissionDeadline?$r->first_submitted_at->lte(\Illuminate\Support\Carbon::parse($submissionDeadline)):null,'allowed'=>app(CreativeWorkflow::class)->allowed($r,$actor),'can_replan'=>!$r->is_group&&CreativeAccess::lead($actor)&&!in_array($r->stage,['in_review','delivered','completed','archived'],true),'can_plan'=>CreativeAccess::lead($actor),'can_comment'=>CreativeAccess::view($actor,$r),'can_acknowledge'=>$r->assignee_id===$actor->id&&!$r->acknowledged_at,'preview'=>$raster?['url'=>route('portal.creative.attachment',$raster),'mime'=>$raster->mime,'name'=>$raster->original_name]:null,
   'dates'=>collect(['received_at','acknowledged_at','reported_external_at','source_recorded_at','requested_deadline','planned_start','internal_eta','first_submitted_at','submitted_at','review_due_at','reviewed_at','delivered_at','completed_at'])->mapWithKeys(fn($key)=>[$key=>$r->$key?->toIso8601String()])->all()];
 }
 public function detail(CreativeRequest $r,User $u,int $page=1,int $feedbackPage=1):array {
  $r->load('requester','assignee','reviewer','attachments','task','firstSubmission');$dto=$this->item($r,$u);
  $history=PerformanceEvent::with('actor')->where('entity_type','creative_request')->where('entity_id',$r->id)->orderByDesc('id')->paginate(40,['*'],'history_page',$page);
  $dto['history']=$history->map(fn($e)=>['id'=>$e->id,'action'=>$e->action,'actor'=>$e->actor?->name??'System / retained staff history','at'=>$e->created_at??$e->occurred_at,'reason'=>$e->reason,'before'=>collect($e->before??[])->only(['stage','assignee_id','requested_deadline','internal_eta'])->all(),'after'=>collect($e->after??[])->only(['stage','assignee_id','requested_deadline','internal_eta'])->all()])->all();
  $dto['history_pages']=['current'=>$history->currentPage(),'last'=>$history->lastPage()];
  $feedback=$r->updates()->with('author')->reorder('id','desc')->paginate(40,['*'],'feedback_page',$feedbackPage);
  $dto['updates']=$feedback->getCollection()->map(fn($m)=>['id'=>$m->id,'author'=>$m->author?->name??'Former staff member','at'=>$m->created_at->toIso8601String(),'kind'=>$m->kind,'body'=>$m->body,'url'=>$m->reference_url,'metadata'=>$m->metadata])->all();
  $dto['feedback_pages']=['current'=>$feedback->currentPage(),'last'=>$feedback->lastPage(),'total'=>$feedback->total()];
  $roundUpdates=$r->updates()->with('author')->whereIn('kind',['in_review','changes_requested','delivered','completed'])->orderBy('id')->get();
  $dto['rounds']=$roundUpdates->where('kind','in_review')->map(function($submission)use($roundUpdates){
   $iteration=(int)($submission->metadata['iteration']??0);
   $decisions=$roundUpdates->filter(fn($update)=>(int)($update->metadata['iteration']??-1)===$iteration&&$update->id>$submission->id);
   $correction=$decisions->firstWhere('kind','changes_requested');$approval=$decisions->firstWhere('kind','delivered');
   return ['iteration'=>$iteration,'submitted_at'=>$submission->created_at->toIso8601String(),'submitted_by'=>$submission->author?->name??'Former staff member','feedback_due_at'=>$submission->metadata['review_due_at']??null,'corrections_at'=>$correction?->created_at?->toIso8601String(),'corrections_by'=>$correction?->author?->name,'feedback'=>$correction?->body,'feedback_type'=>$correction?->metadata['feedback_type']??null,'approved_at'=>$approval?->created_at?->toIso8601String(),'approved_by'=>$approval?->author?->name];
  })->values()->all();
  $dto['attachments']=$r->attachments->map(fn($a)=>['id'=>$a->id,'name'=>$a->original_name,'kind'=>$a->kind,'mime'=>$a->mime,'iteration'=>$a->iteration,'at'=>$a->created_at->toIso8601String(),'url'=>route('portal.creative.attachment',$a),'download'=>route('portal.creative.attachment',[$a,'download'=>1])])->all();
  $dto['parts']=$r->parts()->visibleTo($u)->get(['id','reference','title','stage','assignee_id'])->map(fn($p)=>['id'=>$p->id,'reference'=>$p->reference,'title'=>$p->title,'stage'=>config('creative.stages.'.$p->stage)])->all();$dto['can_split']=CreativeAccess::lead($u)&&!$r->task_id&&!$r->assignee_id&&!$r->is_group&&!$r->parent_request_id&&in_array($r->stage,['backlog','brief_received','needs_info']);
  $dto['sources']=DB::table('creative_sources')->where('creative_request_id',$r->id)->get(['source_type','source_id'])->all();
  $dto['legacy_comments']=$r->task_id?CreativeComment::with('user')->where('task_id',$r->task_id)->latest()->limit(50)->get()->map(fn($c)=>['author'=>$c->user?->name??'Former staff member','at'=>$c->created_at->toIso8601String(),'body'=>$c->comment??$c->message??$c->body??'Historical proofing comment','attachment'=>$c->attachment_path?true:false])->all():[];
  $dto['alerts']=\App\Models\PerformanceOutbox::where('url',route('portal.creative',['request'=>$r->id]))->with('user')->latest('id')->limit(30)->get()->map(fn($n)=>['recipient'=>$n->user?->name??'Former staff member','title'=>$n->title,'queued_at'=>$n->created_at,'in_app_at'=>$n->dashboard_at,'email_at'=>$n->emailed_at,'attempts'=>$n->attempts,'status'=>$n->last_error?'Retry needed':($n->dashboard_at?'In-app delivered':'Queued')])->all();
  return $dto;
 }
}
